<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Offer\Action\Command;

use Module\Offer\Action\Command\ChangeVisibilityCmd;
use Module\Offer\Action\Dto\Admin\ChangeVisibilityDto;
use Module\Offer\Model\Offer;
use Module\Offer\Model\OfferRepository;
use Module\Shared\Exception\AppEntityVersionException;
use Module\Shared\Exception\AppValidationException;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class ChangeVisibilityCmdTest extends IntegrationTestCase
{
    private const int OFFER_ID = 501;

    private ChangeVisibilityCmd $sut;

    private OfferRepository $offerRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->offerRepository = $this->container->get(OfferRepository::class);

        $this->sut = new ChangeVisibilityCmd($this->offerRepository);

        $this->prepareDb();
    }

    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        int $offerId,
        int $version,
        bool $visible,
        string $expectedExceptionClass,
        string $expectedExceptionMessage,
        ?bool $expectedVisible,
        ?int $expectedVersion,
    ): void {
        if ($expectedExceptionClass) {
            $this->expectException($expectedExceptionClass);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $this->sut->handle(new ChangeVisibilityDto($offerId, $version, $visible));

        if ($expectedVisible !== null) {
            $offer = $this->offerRepository->find($offerId);
            $this->assertSame($expectedVisible, $offer->isVisible());
            $this->assertSame($expectedVersion, $offer->getVersion());
        }
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'offer not found' => [
                'offerId' => 9999,
                'version' => 0,
                'visible' => false,
                'expectedExceptionClass' => AppValidationException::class,
                'expectedExceptionMessage' => 'id: Offer not found',
                'expectedVisible' => null,
                'expectedVersion' => null,
            ],
            'version mismatch' => [
                'offerId' => self::OFFER_ID,
                'version' => 99,
                'visible' => false,
                'expectedExceptionClass' => AppEntityVersionException::class,
                'expectedExceptionMessage' => 'Entity version in database is different than version received in API call.',
                'expectedVisible' => null,
                'expectedVersion' => null,
            ],
            'hide offer' => [
                'offerId' => self::OFFER_ID,
                'version' => 0,
                'visible' => false,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedVisible' => false,
                'expectedVersion' => 1,
            ],
            'show offer' => [
                'offerId' => self::OFFER_ID,
                'version' => 0,
                'visible' => true,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedVisible' => true,
                'expectedVersion' => 1,
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->offerRepository->saveWithId(
            Offer::factory(
                storeId: 1,
                externalId: 'EXT-501',
                productEan: '5901234123457',
                productName: 'Test Product',
                price: 1000,
                visible: true,
                version: 0,
                id: self::OFFER_ID,
            )
        );
        $this->offerRepository->flush();
    }
}
